  private java.util.function.Consumer<Boolean> paged(ListView<JsonObject> target,String action,String key,int maximum,String requestCursor,String responseCursor,int pageSize){String[] cursor={""};long[] generation={0};return more->{if(more&&(cursor[0].isEmpty()||target.getItems().size()>=maximum)){status.setText(cursor[0].isEmpty()?"Все полученные страницы показаны.":"Достигнут предел текущего списка. Обновите список для новых данных.");return;}if(!more){cursor[0]="";generation[0]++;target.getItems().clear();}long version=generation[0];api.call(action,obj("limit",pageSize,requestCursor,cursor[0]),status,r->{if(generation[0]!=version)return;Set<String> known=new HashSet<>();for(JsonObject row:target.getItems())known.add(row.has("id")?str(row,"id"):str(row,"identity"));for(JsonObject row:items(r,key)){String id=row.has("id")?str(row,"id"):str(row,"identity");if(target.getItems().size()<maximum&&known.add(id))target.getItems().add(row);}cursor[0]=str(r,responseCursor);if(target.getItems().size()>=maximum&&!cursor[0].isEmpty())status.setText("Показана часть списка: "+maximum+" записей. Обновите список для новых данных.");});};}
